  function taskOps(r){
    if(r.approval==='审核中')return link('详情',`/tasks/${r.id}`);
    if(r.approval==='已驳回')return `${link('详情',`/tasks/${r.id}`)}${link('修改数据',`/tasks/${r.id}/entry`)}<button class="btn-link" data-action="submit-review" data-id="${r.id}">重新提交审核</button>`;
    if(r.status==='待派发')return `<button class="btn-link" data-action="assign" data-id="${r.id}">指派</button>${link('详情',`/tasks/${r.id}`)}`;
    if(r.status==='待检测')return `${r.equipment&&r.received?`<button class="btn-link" data-action="start-task" data-id="${r.id}">开始检测</button>`:`<button class="btn-link" disabled title="请先完成设备申请及领用">开始检测</button>`}${link('详情',`/tasks/${r.id}`)}<button class="btn-link danger" data-action="reject-task" data-id="${r.id}">拒绝</button><button class="btn-link" data-action="transfer" data-id="${r.id}">转派</button>`;
    if(r.status==='检测中')return `${link('详情',`/tasks/${r.id}`)}${link('录入数据',`/tasks/${r.id}/entry`)}<button class="btn-link" data-action="submit-review" data-id="${r.id}">提交审核</button>`;
    if(r.status==='检毕')return `${link('详情',`/tasks/${r.id}`)}<button class="btn-link" data-action="return-task" data-id="${r.id}">退回修改</button>`;
    return link('详情',`/tasks/${r.id}`);
  }
