  function sampleDetail(id){const r=DB.samples.find(x=>x.taskId===id)||DB.samples[0];return pageShell('样品详情',`<div class="detail-page">${detailSection('样品信息',[desc('检测任务编号',r.taskId),desc('桩号/检测部位',r.position),desc('检测项目',r.item),desc('委托单编号',r.entrustId),desc('关联委托单名称',r.entrust),desc('检测人员',r.inspector),desc('图片数量',`${r.imageCount} 张`),desc('创建时间',r.created)])}<section class="detail-section"><div class="detail-title">当前样品图片</div><div class="photo-grid">${Array.from({length:r.imageCount},(_,i)=>`<button class="photo" data-action="photos" data-id="${r.taskId}"><span>样品图 ${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div></section><section class="detail-section"><div class="detail-title">图片维护记录</div><div class="timeline"><div class="timeline-item"><strong>补传图片</strong><div class="timeline-meta">王工 · 2026-08-28 17:20 · 补传现场全景图</div></div></div></section></div>`,'检测管理',`<button class="btn btn-primary" data-action="maintain-photos" data-id="${r.taskId}">维护图片</button>`)}
  function reportGenerate(){const eligible=DB.tasks.filter(x=>x.status==='检毕');const extra=DB.tasks.slice(5,11).map(x=>({...x,status:'检毕',approval:'审核通过',entrustId:'WT202608280001',item:'桩承载力检测'}));const rows=eligible.concat(extra);return pageShell('生成报告',`<div class="form-page">${formSection('生成条件',[formItem('关联委托单',`<select id="reportEntrust" class="control"><option>WT202608280001 / 滨河新城1号楼桩基委托</option></select>`,{required:true,wide:true}),formItem('检测项目',`<select id="reportItem" class="control"><option>桩承载力检测</option></select>`,{required:true})])}<section class="section"><div class="section-title">选择检毕任务</div><div class="alert info">一期仅允许选择同一委托单、同一检测项目、且未被其他有效报告占用的检毕任务；可选择部分任务生成报告。</div>${table([{label:'任务编号',key:'id'},{label:'桩号/检测部位',key:'position'},{label:'检测项目',key:'item'},{label:'任务状态',render:r=>tag(r.status)},{label:'占用状态',render:()=>tag('未占用')}],rows)}</section><div class="sticky-actions"><a class="btn" href="#/tasks">取消</a><button class="btn btn-primary" data-action="generate-report">生成报告</button></div></div>`,'检测管理');}
  function reportForm(r=null){return pageShell(r?'编辑报告':'编制报告',`<form id="reportForm" data-edit-id="${r?.id||''}" class="form-page">${detailSection('报告基本信息',[desc('报告编号',r?.id||'保存后系统生成'),desc('关联委托单',r?.entrust||'WT202608280001'),desc('检测项目','桩承载力检测'),desc('关联任务数量',`${r?.taskCount||3} 项`),desc('编制人',r?.author||currentUser.name),desc('报告状态',tag(r?.status||'编制中'))])}<section class="section"><div class="section-title">主报告附件</div><div class="alert info">一个报告仅允许上传一个主附件。保存时可暂不上传，发起审核前必须已有附件。</div>${r?.attachment?`<div class="file-row"><span>▧ ${r.attachment}</span><span><a>预览</a>　<a>删除</a></span></div>`:''}<div class="upload-box" data-action="upload" style="margin-top:10px"><button type="button" class="btn btn-primary">＋ 上传${r?.approval==='已驳回'?'新版本':'报告'}附件</button><p>支持 DOC、DOCX、PDF 文件${r?.approval==='已驳回'?'；驳回后必须上传新文件形成新版本':''}</p></div></section><div class="sticky-actions"><a class="btn" href="#/reports">取消</a><button class="btn btn-primary" type="submit">保存</button></div></form>`,'检测管理');}
  function reportDetail(id){const r=DB.reports.find(x=>x.id===id)||DB.reports[0];return pageShell('报告详情',`<div class="detail-page">${r.status==='已作废'?'<div class="void-watermark">已作废</div>':''}${detailSection('报告信息',[desc('报告编号',r.id),desc('关联委托单',r.entrust),desc('关联任务',`<button class="btn-link link-number" data-action="report-tasks" data-id="${r.id}">${r.taskCount} 项</button>`),desc('创建时间',r.created),desc('编制人',r.author),desc('报告状态',tag(r.status)),desc('审核状态',tag(r.approval)),desc('当前版本',`V${r.version}`)])}<section class="detail-section"><div class="detail-title">主报告附件</div>${r.attachment?`<div class="file-row"><span>▧ ${r.attachment}</span><span class="file-actions"><a>在线预览</a><a>下载</a></span></div>`:'<div class="empty" style="height:130px">暂无报告附件</div>'}</section><section class="detail-section"><div class="detail-title">报告历史版本</div>${Array.from({length:r.version},(_,i)=>`<div class="file-row"><span>V${i+1}　检测报告_${r.id}_V${i+1}.pdf</span><span class="file-actions"><a>预览</a><a>下载</a></span></div>`).join('')}</section><section class="detail-section"><div class="detail-title">审核记录</div><div class="timeline"><div class="timeline-item"><strong>${r.approval}</strong><div class="timeline-meta">授权签字人 · 2026-08-29 16:40 · ${r.approval==='已驳回'?'数据图表与原始记录不一致':'审核完成'}</div></div></div></section></div>`,'检测管理',r.status==='已完成'?`<button class="btn" data-action="export">导出</button><button class="btn btn-danger" data-action="void-report" data-id="${r.id}">作废</button>`:'')}
  function equipmentApplicationForm(){return pageShell('新增设备申请',`<form id="equipmentApplicationForm" class="form-page">${formSection('申请信息',[formItem('关联检测任务',`<select id="applicationTask" class="control"><option value="">请选择待检测任务</option>${DB.tasks.filter(x=>['待检测','检测中'].includes(x.status)).map(x=>`<option value="${x.id}">${x.id} / ${x.position} / ${x.item}</option>`)}</select>`,{required:true,wide:true}),formItem('申请人',`<input class="control readonly" value="${currentUser.name}" readonly>`),formItem('预计领用日期',`<input class="control" type="date" value="2026-09-01">`,{required:true}),formItem('用途说明',`<textarea class="control">用于检测任务现场检测</textarea>`,{wide:true})])}<section class="section"><div class="section-title">申请设备（一张申请可包含多台设备）</div>${table([{label:'选择',render:r=>`<input class="checkbox application-device" type="checkbox" data-id="${r.id}">`},{label:'设备编号',key:'id'},{label:'设备名称',key:'name'},{label:'规格型号',key:'model'},{label:'设备状态',render:r=>tag(r.status)},{label:'校准有效期',key:'calibration'}],DB.equipment.filter(x=>x.status==='在库'),{check:false})}<div class="alert info" style="margin-top:15px">设备申请不需要审批，当前一期不考虑部分领用。任务进入检测中后设备关联不可修改。</div></section><div class="sticky-actions"><a class="btn" href="#/equipment/applications">取消</a><button class="btn btn-primary" type="submit">保存申请</button></div></form>`,'基础数据');}

  function relatedInvoiceTable(count=3){
    const rows=DB.invoices.filter(x=>x.status==='正常').slice(0,count).map((x,i)=>({...x,writeoff:Number(x.amount)*(.25+i*.1),received:Number(x.amount)*.4}));
    return table([{label:'发票票号',key:'id'},{label:'发票金额',render:r=>money(r.amount)},{label:'本次核销金额',render:r=>money(r.writeoff)},{label:'累计已收',render:r=>money(r.received)},{label:'剩余未收',render:r=>money(Number(r.amount)-r.received-r.writeoff)},{label:'当前收款状态',render:r=>tag(r.payment)}],rows,{check:false});
  }
  function taskPopupTable(count=5){const rows=DB.tasks.slice(0,count);return table([{label:'任务编号',key:'id'},{label:'委托单编号',key:'entrustId'},{label:'委托单名称',key:'entrust'},{label:'桩号/检测部位',key:'position'},{label:'检测项目',key:'item'},{label:'报告编号',render:()=> '—'}],rows,{check:false})}
