    $('#invoiceForm')?.addEventListener('submit',e=>{e.preventDefault();if(!$('#invoiceCustomer').value||!$('#invoiceContract').value||!$('#invoiceNo').value||Number($('#invoiceAmount').value)<=0||$('#selectedTaskText').textContent==='未选择')return toast('请按客户→合同→任务→发票信息顺序完整填写','error');if(DB.invoices.some(x=>x.id===$('#invoiceNo').value))return toast('发票票号已存在（作废票号仍占用）','error');const c=DB.customers.find(x=>x.id===$('#invoiceCustomer').value),ct=DB.contracts.find(x=>x.id===$('#invoiceContract').value);DB.invoices.unshift({id:$('#invoiceNo').value,customer:c.name,contract:ct.id,contractName:ct.name,amount:Number($('#invoiceAmount').value).toFixed(2),taskCount:3,date:$('#invoiceDate').value,status:'正常',payment:'未收款',paymentTime:'—',attachment:'增值税发票.pdf'});saveDB();toast('开票信息保存成功');location.hash='#/invoices'});
